export const BACKGROUND_BY_ID = Object.fromEntries(BACKGROUNDS.map((b) => [b.id, b]));

export function backgroundByRoll(d20) {
  return BACKGROUNDS[Math.max(0, Math.min(19, d20 - 1))];
}
